// Copies the colour tokens from src/styles/tokens.css (the desktop's single source, PLAN D198)
// into a module the phone app reads: light and dark values, and each accent preset per theme.
// Run after changing tokens.css; src/shared.test.ts fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";

const CSS = "src/styles/tokens.css";
export const OUT = "mobile/src/theme/tokens.ts";

const hexes = (text) => Object.fromEntries([...text.matchAll(/--([a-z0-9-]+):\s*(#[0-9A-Fa-f]{3,8})\b/g)].map((m) => [m[1], m[2].toUpperCase()]));
const block = (css, selector) => {
  const start = css.indexOf(`${selector} {`);
  if (start < 0) throw new Error(`${selector} not found in ${CSS}`);
  return css.slice(start, css.indexOf("\n}", start));
};

export function render() {
  const css = readFileSync(CSS, "utf8");
  const light = hexes(block(css, ":root"));
  const dark = hexes(block(css, ':root[data-theme="dark"]'));
  const accents = {};
  for (const m of css.matchAll(/^((?:\[data-theme="dark"\])?)\[data-accent="([a-z]+)"\][^{]*\{([^}]*)\}/gm)) {
    accents[m[2]] ??= { light: {}, dark: {} };
    Object.assign(accents[m[2]][m[1] ? "dark" : "light"], hexes(m[3]));
  }
  // The default accent (indigo) lives in the theme blocks themselves.
  const pick = (t) => Object.fromEntries(Object.entries(t).filter(([k]) => k.startsWith("accent")));
  accents.indigo = { light: pick(light), dark: { ...pick(dark), ...(accents.indigo?.dark ?? {}) } };
  const json = JSON.stringify({ light, dark, accents }, null, 2);
  return `// Generated by scripts/mobile-tokens.mjs from ${CSS}. Do not edit.\nexport const TOKENS = ${json} as const;\n`;
}

if (process.argv[1]?.endsWith("mobile-tokens.mjs")) {
  writeFileSync(OUT, render());
  console.log(`Wrote ${OUT}`);
}
